import{_ as r,C as t,o,c as i,j as e,a as l,E as n,a5 as s}from"./chunks/framework.DNkHA0lr.js";const _=JSON.parse('{"title":"如何作为数字写手年赚100万美元","description":"","frontmatter":{"title":"如何作为数字写手年赚100万美元","originalTitle":"How To Make $1 Million A Year As A Digital Writer","date":"2023-09-23","originalUrl":"https://thedankoe.com/letters/how-to-make-1-million-a-year-as-a-digital-writer/","minutes":12,"sourceHash":"557440afe7f61c62ae1a1d289ad3db8a49d02c2681fb418c09170300b3ee117c","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/how-to-make-1-million-a-year-as-a-digital-writer/"}]]},"headers":[],"relativePath":"letters/how-to-make-1-million-a-year-as-a-digital-writer.md","filePath":"letters/how-to-make-1-million-a-year-as-a-digital-writer.md"}'),h={name:"letters/how-to-make-1-million-a-year-as-a-digital-writer.md"};function d(m,p,c,f,u,g){const a=t("ArticleMeta");return o(),i("div",null,[p[0]||(p[0]=e("h1",{id:"如何作为数字写手年赚100万美元",tabindex:"-1"},[l("如何作为数字写手年赚100万美元 "),e("a",{class:"header-anchor",href:"#如何作为数字写手年赚100万美元","aria-label":'Permalink to "如何作为数字写手年赚100万美元"'},"​")],-1)),n(a),p[1]||(p[1]=s('<p><a href="https://www.youtube.com/embed/gtMqg_QWMzA?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>这是数字写手（Digital Writer）系列的开篇。</p><p>在接下来的几周里（中间会穿插几封关于残酷真相和自我提升的信件），我们将深入探讨如何在谈论自己兴趣的同时，成为一名能赚钱的写手。</p><p>我们开始吧。</p><p>在内心深处，我一直是个充满创造力的人。</p><p>我喜欢那种只用一台笔记本电脑工作，能在世界各地生活，且不必为钱发愁的想法。</p><p>很自然地，我学习了平面设计、摄影和电影制作之类的东西。</p><p>这些都是值得学习的宝贵技能，但它们从未真正让我取得什么成就。</p><p>我知道我必须学一些更受市场看重的东西，但我不想放弃我的创意优势。</p><p>就在那时，我在大学里选修了一门网页开发课。</p><p>我着迷了。</p><p>无需学位就能获得高薪工作的前景，以及我能用来极客自学编程的无限资源，都极具诱惑力。</p><p>而且如果我做前端设计，就不必放弃我的创造力。</p><p>创造力加上编程似乎比单纯的平面设计更有价值，但这仅仅是针对就业市场而言（以我当时的认知水平来看）。</p><p>我一直想做自己的事情。</p><p>找份工作简直是我人生痛苦的根源。</p><p>观察社会并不难，你会发现大多数人都超重且不快乐。他们的共同点是，他们最宝贵的资源——时间——都被一份把他们往死里用的工作给吸干了。</p><p>长话短说，我从来没能把我的创造力变现。</p><p>这不是因为我的技术不够好，而是因为我没有叠加其他能让我赚钱的技能。我没有掌握那些能让我把主业技能变现的正确技能。这又是“只专注于一件事”的又一次败笔。</p><p>我会在以后的信件中讲述我的完整故事，但现在你只需知道，那条路没走通。</p><p>我只好咽下骄傲，去找了份工作。</p><p>幸运的是，我成功拿到了我申请的第一份网页设计工作，因为我花了一年时间自学编程（而且在这之前我有设计经验）。</p><p>经验教训：</p><p>你不需要上学也能找到高薪工作。</p><p>那份工作可以作为你建立自己事业的发射台。</p><p>在我们开始之前，《专注的艺术》（The Art Of Focus）纪念礼盒已开放预购：</p><ul><li>纪念版精装书——我们只印制了2000本。</li><li>本书的数字下载版，让你能先睹为快。</li><li>录制并上传后的有声书版本。</li><li>FOCI计划本，用于将你理想的未来解构为优先任务。</li><li>FOCI硬币，提醒你要有意识地行动。</li><li>数字化转型中心，包含12小时的现代创业培训。</li><li>用于获取更新、讨论和拓展人脉的私密社区。</li><li>明年在亚利桑那州凤凰城举行的线下活动的私人邀请函。</li></ul><p>在正式发售日之前，价格会上涨两次。</p><h2 id="我是如何作为一名数字写手赚到数百万的" tabindex="-1">我是如何作为一名数字写手赚到数百万的 <a class="header-anchor" href="#我是如何作为一名数字写手赚到数百万的" aria-label="Permalink to &quot;我是如何作为一名数字写手赚到数百万的&quot;">​</a></h2><p>我在一家网页设计机构工作了一年。</p><p>这是一件幸事，因为它向我展示了我的自由职业网页设计业务中究竟缺失了哪些拼图。</p><p>那家机构有营销部、销售部和运营部。</p><p>营销和销售部门负责获取并转化潜在客户。</p><p>运营部门将他们交接给设计师（也就是我）。</p><p>我建好他们的网站，然后交付给他们。</p><p>这很有道理，所以我开始学习文案写作、销售、直接回应营销，以及其他人告诉你要去学的所有其他技能。</p><p>在空闲时间，我会尝试天底下所有的方法来获取客户。</p><p>冷邮件。<br> 冷电话。<br> 冷私信。<br> 在Facebook群组里拓展人脉。<br> 投放Facebook和Google的付费广告。<br> 走进当地的实体店直接跟经理交谈。<br> 从服务型企业的面包车车身广告上抄下他们的电话号码（比如害虫防治公司）。</p><p>我开始拿到了几个客户，但远远达不到我想要的数量。别误会，在网页设计机构工作的那一年里，我确实替换了我的工资收入并辞去了工作。</p><p>但我想要的不仅仅是替换掉我的工资收入。</p><p>我想赚几百万……毕竟谁不想呢？</p><p>我当时过得还不错，一年能赚近10万美元——主要是在付出了大量体力劳动后通过推荐客户得来的——并且我也能够辞职了。</p><p>这时候发生了一些事情。</p><p>而且这些事情只能在这个阶段发生，因为如果没有我之前的经历和失败，我的大脑根本无法理解它们。</p><p><strong>1) 我开始理解社交媒体的力量。</strong></p><p>我到底为什么要干这么多体力活去拉客户？</p><p>我为什么没意识到，那些发布内容并积累了粉丝的人，手头有着无限的客户（只要他们懂营销和销售）？</p><p>如果我能建立受众群体，那每周就能为我的自由职业省下10到20个小时的获客时间。</p><p>而且，如果我建立的粉丝群足够大，我就能转型脱离客户服务工作。那会给我省下更多的时间，因为我可以通过数字或实体产品来变现。</p><p>你可以开始看出我的“每天工作4小时”理念是从哪里来的了。</p><p><strong>2) 我拥有在X（推特）上增长的经验。</strong></p><p>几个世纪前，有一个名叫Twitter的社交媒体应用。</p><p>我以前从来没把心思放在它身上。</p><p>但出于某种原因，我开始越来越频繁地使用它。</p><p>我注意到人们在谈论我喜欢的一切。</p><p>自我提升、思维方式、哲学、网页设计、商业、营销等等。这些经常出自同一个账号。他们似乎并不限制自己谈论的话题，因为很明显它们都有重叠之处（就像这封新闻信可以被归类到这些话题中的任何一个一样）。他们告诉你“要选择一个细分领域（niche）”，但他们自己却没有。<a href="/letters/niche-down-is-terrible-advice-for-smart-people">他们细化的是产品和服务，而不是他们的个人品牌。</a></p><p>如果他们能用内容产生流量，并且拥有他们所说的成功事业……我为什么不能做同样的事呢？</p><p>我开始模仿他们的内容结构，把脑子里的想法发出来。</p><p>记住，我之前学过文案写作和直接回应营销的知识。</p><p>我知道该怎么写一篇帖子才能抓住眼球，并激起足够的兴趣让人关注我。</p><p>第一年，我获得了大约10,000名粉丝。</p><p>第二年，涨到了50,000。</p><p>第三年，再次跃升至100,000。</p><p>然后，我用我已经验证过的想法在其他平台发帖，比如Instagram、LinkedIn和YouTube。我知道它们会获得很高的互动，因为我从推特写作中积累了大量数据。</p><p>今天，4年过去了，我在所有平台上大约有2,800,000名粉丝。</p><p>这就是所谓的指数级增长，以及为什么说坚持才是王道。</p><p>关于社交媒体增长，还有很多可聊的。我很快会在一封名为《如何真正在社交媒体上实现增长（他们没告诉你的事）》（<em>How To Actually Grow On Social Media (What They Don’t Tell You)</em>）的信中谈论这点。<a href="/letters/how-to-network-with-millionaires-and-build-a-name-for-yourself">现在你可以先阅读这篇关于拓展人脉的信件</a>。</p><p><strong>3) 一切都指向写作。</strong></p><p>在推特上写作让我意识到了一件事。</p><p><em>我不只是在推特上写作。</em></p><p>我当时在写邮件、新闻信、落地页、促销文案、视频脚本、私信、课程大纲、产品资料……一切都在写。</p><p>没过多久，我就把自己当成了一个写手。</p><p>这就是我每天早上做的唯一一件事。</p><p>那是我业务所有增长的驱动力。</p><p>我抓取注意力、创造价值和影响读者的能力，全都归功于写作。</p><p>这就是 <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a> 诞生的过程。那是我教授整个写作生态系统的课程。因为商业中的一切——不管你做什么——都是从写作开始的。</p><p>大多数写手都想出售他们的文字，他们确实可以通过付费博客、新闻信或社群来做到这一点，但这局限性太大了。</p><p>写作既是产生流量的机制，也是创造信息产品的方式。</p><p>当你知道如何写作、营销和销售时，你就可以通过写任何你想写的内容来赚取收入。</p><p><strong>4) 我的收入随着读者群的增加而增长。</strong></p><p>几年前我读到一条推特，说你每个月可以从每个粉丝身上赚到0.50到1美元（当然是凭借你自己的产品或服务，而不是靠平台变现或Adsense广告）。</p><p>直到某一刻，这在我身上都得到了验证。</p><p>在第1年到第3年期间，我每个月大概能从每个粉丝身上赚到1美元。</p><p>所以，先是1万美元，然后是5万美元，接着是10万美元。</p><p>我在第三年赚了80万美元。</p><p>过去的一年里，我的收入已经超过了我的粉丝总数，到目前为止大约是310万美元。</p><p>这里面有很多技术细节，但有一点是肯定的：</p><p>如果你慢慢建立起一定规模的读者群，推出一个新产品，并且做对了80%的事情，我很难相信你会赚不到100万美元。</p><p>到了这个时候，如果你坚持下来，这条路径对你来说应该是一目了然的。</p><p>我看到的主要陷阱是，人们在玩短期的金钱游戏。用劣质产品的促销信息轰炸他们的受众，并且从不改进他们所提供的产品。</p><h2 id="将写作变现的原则" tabindex="-1">将写作变现的原则 <a class="header-anchor" href="#将写作变现的原则" aria-label="Permalink to &quot;将写作变现的原则&quot;">​</a></h2><p>我不想给你什么黑客技巧和战术。</p><p>这是一场长期游戏。</p><p>你越早接受这一点，就能越早取得结果，因为最快的捷径往往是走最长的弯路。</p><p>相反，我想给你一些值得关注的原则。</p><p>这些将是你将写作变现的主要驱动力。</p><h3 id="_1-分发渠道——选择一个写作平台" tabindex="-1">1) 分发渠道——选择一个写作平台 <a class="header-anchor" href="#_1-分发渠道——选择一个写作平台" aria-label="Permalink to &quot;1) 分发渠道——选择一个写作平台&quot;">​</a></h3><p>分发渠道是你连接产品和人群的桥梁。</p><p>对于写手来说，社交媒体就是你实现这一目标的途径。</p><p>你不需要非得在写作平台上起步，但你为什么不呢？</p><p>你不需要发你身材的照片。</p><p>你可以把学习和产生想法放在首位。</p><p>你不需要设计图片或者剪辑视频。</p><p>除非你以后想扩张业务，否则这是一种相当安逸的生存状态。</p><p>我建议将X（推特）作为你的起点，因为你可以通过我们稍后会讨论的策略来控制增长。</p><p>Medium、博客网站和新闻信的增长速度要慢得多。</p><p>在我看来，先在X上积累粉丝，日后再将受众转移到长文写作上，这会更容易一些。</p><h3 id="_2-产品-offer-——你如何通过受众变现" tabindex="-1">2) 产品（Offer）——你如何通过受众变现 <a class="header-anchor" href="#_2-产品-offer-——你如何通过受众变现" aria-label="Permalink to &quot;2) 产品（Offer）——你如何通过受众变现&quot;">​</a></h3><p>新手倾向于看到YouTube博主通过广告收入赚大钱，就认为那是最好的变现方式。</p><p>甚至现在X也开通了创作者变现……我看到这种情况越来越多了。</p><p>可以说，这是最愚蠢的想法。</p><p>你开始做这件事，是因为你想在生活中拥有更多的自主权。</p><p>不要做算法的奴隶。</p><p>你必须创造属于自己的产品或服务。</p><p>如果是我，我会这样做：</p><ul><li><strong>开启自由职业。</strong> 起初你不会有大量粉丝。所以你需要做更多手动工作，以比卖课程等更高的价格去拿下写作客户。这能让你获得收入。（你可以出售社交媒体内容、文案、邮件等。只是千万别只提供普通的“单纯写作”。）</li><li><strong>逐渐摆脱手动获客。</strong> 随着受众增长，你可以利用这一点（加杠杆）来获取客户。这能为你腾出时间去开始打造产品。</li><li><strong>将自由职业服务产品化。</strong> 你可以继续做自由职业，但拥有数字产品、课程或实体产品能让你无需手动劳动即可赚钱。</li><li><strong>随心所欲。</strong> 到了这个阶段，你应该具备了心智和财务资源，去打造任何你想打造的东西并将其变现。尽情享受完善的技能栈和经验所带来的自由吧。</li></ul><p>最后一件事情，大多数人打造了产品却看不到任何结果。我建议你报名 <a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">数字经济学（Digital Economics）</a> 来学习我的变现系统，或者阅读我之前关于 <a href="/letters/value-creation-the-skill-that-built-my-one-person-business">价值创造（Value Creation）</a> 的文章。</p><h3 id="_3-杠杆与可扩展性" tabindex="-1">3) 杠杆与可扩展性 <a class="header-anchor" href="#_3-杠杆与可扩展性" aria-label="Permalink to &quot;3) 杠杆与可扩展性&quot;">​</a></h3><p>如果你不优先考虑杠杆和可扩展性，你就无法实现年入100万美元（至少在不痛恨自己生活的情况下是做不到的）。</p><p>互联网让企业无需雇佣海量员工也能实现规模扩张。</p><p>数字工具、软件和自动化让你能够独自完成过去需要10名员工才能完成的工作。</p><p>在你写作和建设的过程中，你必须不断进化你的产品，让它们占用你更少的时间。</p><p>显而易见且当务之急的一步，是将你的服务（比如自由职业）转化为数字产品（比如一门面向更初级的受众教授同类知识的课程）。</p><p>以我为例，我曾经是一名自由网页设计师。</p><p>所以，为了腾出更多时间，我在第一年打造了两款产品。</p><p>一款是教授如何创建网站和落地页的。</p><p>另一款是教授我手动拿下自由职业客户的方法。</p><p>到了第二年，我彻底停掉了自由网页设计的业务。</p><p>有些人即使看到了更好的机会，也会被自己正在做的事情死死套住。</p><p>此时我已经积累了<em>太多</em>的经验。继续做利润更低且更耗时的事情简直毫无意义。</p><p>于是，我转型去为线上企业提供营销咨询。</p><p>反正我在社交媒体上能直接接触到他们。这顺理成章。</p><p>最终，我做了同样的事情。</p><p>我把那个营销咨询变成了一门更昂贵的课程。</p><p>这里的教训是：</p><p>你<em>和</em>你的业务必须持续进化。</p><p>对我而言，这每6个月就会发生一次。</p><p>我<em>能感觉到</em>业务进展变慢并陷入停滞。</p><p>我必须创造新产品和新服务，才能在创业这个狂野西部中生存下来。</p><h3 id="_4-推广——品牌的毁灭者" tabindex="-1">4) 推广——品牌的毁灭者 <a class="header-anchor" href="#_4-推广——品牌的毁灭者" aria-label="Permalink to &quot;4) 推广——品牌的毁灭者&quot;">​</a></h3><p>我谈论我的新书 <em><a href="https://theartoffocusbox.com/" target="_blank" rel="noreferrer">专注的艺术 (The Art Of Focus)</a></em> 已经有将近3年了。</p><p>至今依然有人发私信给我，说他们根本不知道我写了本书。</p><p>仅仅因为某人关注了你或读过你的一篇帖子，并不意味着他们知道能从你这里买什么——哪怕他们就是最完美的受众。</p><p>你。必。须。去。推。广。</p><p>推广意味着告诉人们你的产品或服务，并把他们引导到一个可以阅读更多信息并购买的页面。</p><p>针对这一点，有一个简单的 PAS 框架。</p><ul><li><strong>问题（Problem）</strong> – 通过谈论他们正在面临且你的产品能解决的问题，来抓住他们的注意力。<em>“如果你在……上感到挣扎”</em> 就是一个绝佳的开场白。</li><li><strong>放大（Amplify）</strong> – 谈论这个问题是如何影响他们生活的，以及为什么必须解决它。</li><li><strong>解决方案（Solution）</strong> – 将你的产品定位为该问题的解决方案，引导他们点击并了解更多。</li></ul><p>你可以在帖子的评论区、你的动态快拍（story）里，或是像我刚才那样在文章中随机植入你的产品、服务或新闻通讯。</p><p>每当有人来找我寻求变现方面的帮助时，他们在营销上可能确实存在问题，但绝大多数时候仅仅是因为缺乏推广。</p><p>他们没有设定一个计划，哪怕是每天在任何内容里推广一次。</p><p>这绝对是让你沦为“饥饿艺术家”的必由之路。</p><h3 id="总结-如何作为一名写作者年入100万美元" tabindex="-1">总结：如何作为一名写作者年入100万美元 <a class="header-anchor" href="#总结-如何作为一名写作者年入100万美元" aria-label="Permalink to &quot;总结：如何作为一名写作者年入100万美元&quot;">​</a></h3><p>我希望能告诉你这会很容易，但并非如此。</p><p>其中的原则倒是相当简单明了。</p><p>用写作来建立读者群（如果你懂得在增长停滞时如何去改进，借助互联网，你的读者群能够无限增长）。</p><p>打造一款读者想要的产品（如果卖不出去，那不是他们的错，而是你的问题。去打造一款更好的产品，再试一次）。</p><p>坚持做上好几年，甚至将其作为你余生的事业。</p><p>创业意味着你完全掌控自己能赚多少钱。</p><p>你的收入仅仅受限于你的视角、信念、技能组合以及在真实世界中的实践。</p><p>祝你本周接下来的时间过得愉快。</p><p>Dan Koe</p><p>在这里再次植入 <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2小时写作者 (2 Hour Writer)</a> 顺理成章，所以我就植入了。</p><hr><p><a href="/en/letters/how-to-make-1-million-a-year-as-a-digital-writer">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',164))])}const k=r(h,[["render",d]]);export{_ as __pageData,k as default};
